1	/** ACP v1 stdio transport and runtime adapter for Nexus's existing sidecar protocol. */
2	import * as fs from "node:fs";
3	import * as path from "node:path";
4	import type { HarnessConfig } from "./types.js";
5	import { ApplicationCore } from "./core/app.js";
6	import { pinBase, VerifyService, type PinnedBase, type VerifyServiceDeps } from "./core/verify_service.js";
7	import { formatSafeSidecarDiagnostic, SidecarServer } from "./sidecar.js";
8	import { PROTOCOL_VERSION, SIDECAR_MAX_HISTORY_PAGES, type SidecarEvent } from "./protocol.js";
9	import {
10	  ACP_CANCEL_REQUEST_METHOD, ACP_ERROR, ACP_MAX_INFLIGHT_REQUESTS, ACP_MAX_PENDING_PERMISSIONS_PER_SESSION,
11	  ACP_MAX_OVERSIZED_LINES, ACP_MAX_SESSIONS, ACP_PERMISSION_TIMEOUT_SECS, ACP_RECEIPT_STORE_SIZE, ACP_TOMBSTONE_COUNT,
12	  ACP_VERIFY_METHOD, type AcpId, type AcpVerification,
13	} from "./acp/types.js";
14	import {
15	  BoundedLineReader, RequestCorrelator, encodeMessage, errorResponse, notification,
16	  oversizedLineError, parseMessage, request, resultResponse,
17	} from "./acp/jsonrpc.js";
18	import {
19	  approvalToPermissionRequest, assistantDeltaToUpdate, bindApprovalToToolCall, cancelledRequestError,
20	  fileDiffToUpdate, historyToReplay, initializeResult, loadSessionResult, newSessionResult, nexusReceipt,
21	  permissionReplyToCommand, promptResult, sessionUpdate, sidecarErrorToRpc, toolEndToUpdate, toolStartToUpdate,
22	  turnToStop, verificationFromTurn, verificationUpdate, verdictChunk,
23	} from "./acp/mapping.js";
24	import {
25	  canonicalCwd, validateCancel, validateCancelRequest, validateInitialize, validateLoadSession,
26	  validateNewSession, validatePrompt, validateReceiptGet, validateVerify,
27	} from "./acp/validate.js";
28	
29	type SidecarLike = { start(): void; handleLine(line: string): Promise<void> };
30	type Session = {
31	  id: string; cwd: string; mcp: { count: number; names: string[] }; sidecar: SidecarLike;
32	  verifyBase: PinnedBase | { error: string };
33	  events: SidecarEvent[]; tools: SidecarEvent[]; pendingPrompt?: { rpcId: AcpId; commandId: string };
34	  pendingVerify?: { rpcId: AcpId; controller: AbortController; cancelled: boolean; completion?: Promise<unknown> };
35	  pendingApproval?: { id: string; rpcId: number; toolCallId: string; timer: NodeJS.Timeout };
36	  pendingReceipt?: { commandId: string; resolve: (event: SidecarEvent | undefined) => void };
37	  /** The prompt was answered early (cancelled request, refused checkpoint) and its turn is still winding down: no new prompt until the turn's result arrives, or that result would answer the new prompt. */
38	  stopping?: boolean;
39	};
40	
41	export interface AcpStdioOptions {
42	  config: HarnessConfig;
43	  version: string;
44	  write?: (line: string) => void;
45	  createSidecar?: (config: HarnessConfig, resume: string | undefined, write: (line: string) => void) => SidecarLike;
46	  realpath?: (value: string) => string;
47	  isDirectory?: (value: string) => boolean;
48	  /** How long a signalled process waits for its sessions to stop before it exits anyway. */
49	  shutdownGraceMs?: number;
50	  verifyDeps?: VerifyServiceDeps;
51	}
52	
53	const ACP_SHUTDOWN_GRACE_MS = 10_000;
54	
55	/** One ACP connection. Every session still executes through ApplicationCore and SidecarServer gates. */
56	export class AcpStdioServer {
57	  private readonly write: (line: string) => void;
58	  private readonly reader = new BoundedLineReader();
59	  private readonly permissionRequests = new RequestCorrelator<{ sessionId: string; approvalId: string }>({ tombstones: ACP_TOMBSTONE_COUNT });
60	  private readonly sessions = new Map<string, Session>();
61	  private readonly receipts = new Map<string, ReturnType<typeof nexusReceipt>>();
62	  private readonly latestReceipts = new Map<string, string>();
63	  private readonly pending = new Map<string, AcpId>();
64	  private readonly loadingSessionIds = new Set<string>();
65	  private readonly verifyService: VerifyService;
66	  private startingSessions = 0;
67	  private initialized = false;
68	  private closed = false;
69	
70	  constructor(private readonly options: AcpStdioOptions) {
71	    this.write = options.write ?? ((line) => process.stdout.write(line));
72	    const config = options.config;
73	    this.verifyService = new VerifyService({
74	      verifierCommand: config.authoritativeVerifierCommand,
75	      deliverables: config.trustedDeliverableFiles ?? [],
76	      timeoutSecs: config.verifierTimeoutSecs,
77	      readOnly: Boolean(config.readOnly) || config.approvalMode === "read-only",
78	      surface: "acp",
79	    }, options.verifyDeps);
80	  }
81	
82	  /** Feed raw stdin bytes. Invalid/oversized lines are answered without retaining unbounded input. */
83	  push(chunk: Uint8Array): void {
84	    if (this.closed) return;
85	    for (const event of this.reader.push(chunk)) {
86	      if (this.closed) break;
87	      if (event.kind === "oversized") {
88	        this.write(encodeMessage(oversizedLineError()));
89	        if (this.reader.oversizedLines >= ACP_MAX_OVERSIZED_LINES) void this.close();
90	      }
91	      else void this.receive(event.text);
92	    }
93	  }
94	
95	  async close(): Promise<void> {
96	    this.closed = true;
97	    const shutdowns: Promise<void>[] = [];
98	    for (const session of this.sessions.values()) {
99	      session.pendingVerify?.controller.abort();
100	      if (session.pendingVerify?.completion) shutdowns.push(session.pendingVerify.completion.then(() => undefined));
101	      if (session.pendingApproval) clearTimeout(session.pendingApproval.timer);
102	      shutdowns.push(session.sidecar.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, type: "shutdown" })));
103	    }
104	    this.sessions.clear();
105	    this.pending.clear();
106	    this.latestReceipts.clear();
107	    await Promise.allSettled(shutdowns);
108	  }
109	
110	  private send(message: object): void {
111	    if (!this.closed) this.write(encodeMessage(message));
112	  }
113	
114	  private requestKey(id: AcpId): string { return `${typeof id}:${String(id)}`; }
115	
116	  private async receive(line: string): Promise<void> {
117	    const incoming = parseMessage(line);
118	    if (incoming.kind === "invalid") {
119	      if (incoming.respond) this.send(errorResponse(incoming.id, incoming.error));
120	      return;
121	    }
122	    if (incoming.kind === "response") {
123	      const settled = this.permissionRequests.settle(incoming.id);
124	      if (settled.state !== "matched") return;
125	      const session = this.sessions.get(settled.context.sessionId);
126	      if (!session?.pendingApproval || session.pendingApproval.rpcId !== incoming.id) return;
127	      const pending = session.pendingApproval;
128	      clearTimeout(pending.timer);
129	      session.pendingApproval = undefined;
130	      const command = permissionReplyToCommand(pending.id, incoming);
131	      await this.sidecarCommand(session, command.type === "approve"
132	        ? { type: "approve", id: command.id, always: false }
133	        : { type: "deny", id: command.id });
134	      return;
135	    }
136	    if (this.pending.size >= ACP_MAX_INFLIGHT_REQUESTS && incoming.kind === "request") {
137	      this.send(errorResponse(incoming.id, { code: ACP_ERROR.INTERNAL_ERROR, message: "too many requests are in flight" }));
138	      return;
139	    }
140	    if (incoming.kind === "request") this.pending.set(this.requestKey(incoming.id), incoming.id);
141	    try {
142	      await this.dispatch(incoming);
143	    } catch (err) {
144	      if (incoming.kind === "request") this.replyError(incoming.id, { code: ACP_ERROR.INTERNAL_ERROR, message: formatSafeSidecarDiagnostic([err]) });
145	    } finally {
146	      const promptStillRunning = incoming.kind === "request" && incoming.method === "session/prompt"
147	        && [...this.sessions.values()].some((session) => session.pendingPrompt?.rpcId === incoming.id);
148	      const verifyStillRunning = incoming.kind === "request" && incoming.method === ACP_VERIFY_METHOD
149	        && [...this.sessions.values()].some((session) => session.pendingVerify?.rpcId === incoming.id);
150	      if (incoming.kind === "request" && !promptStillRunning && !verifyStillRunning) this.pending.delete(this.requestKey(incoming.id));
151	    }
152	  }
153	
154	  private replyError(id: AcpId, error: { code: number; message: string; data?: unknown }): void {
155	    this.send(errorResponse(id, error as any));
156	  }
157	
158	  private async dispatch(message: Exclude<ReturnType<typeof parseMessage>, { kind: "invalid" | "response" }>): Promise<void> {
159	    if (message.kind === "request" && !this.initialized && message.method !== "initialize") {
160	      this.replyError(message.id, { code: ACP_ERROR.INVALID_REQUEST, message: "initialize must be the first request" });
161	      return;
162	    }
163	    if (message.method === "initialize" && message.kind === "request") {
164	      if (this.initialized) { this.replyError(message.id, { code: ACP_ERROR.INVALID_REQUEST, message: "initialize was already completed" }); return; }
165	      const parsed = validateInitialize(message.params);
166	      if (!parsed.ok) { this.replyError(message.id, parsed.error); return; }
167	      this.initialized = true;
168	      this.send(resultResponse(message.id, initializeResult({ version: this.options.version, sidecarProtocol: PROTOCOL_VERSION })));
169	      return;
170	    }
171	    if (!this.initialized) return;
172	    if (message.method === "session/new" && message.kind === "request") return this.newSession(message.id, message.params);
173	    if (message.method === "session/load" && message.kind === "request") return this.loadSession(message.id, message.params);
174	    if (message.method === "session/prompt" && message.kind === "request") return this.prompt(message.id, message.params);
175	    if (message.method === ACP_VERIFY_METHOD && message.kind === "request") return this.verify(message.id, message.params);
176	    if (message.method === "session/cancel" && message.kind === "notification") {
177	      const parsed = validateCancel(message.params);
178	      if (parsed.ok) { const session = this.sessions.get(parsed.value.sessionId); if (session) await this.sidecarCommand(session, { type: "cancel" }); }
179	      return;
180	    }
181	    if (message.method === ACP_CANCEL_REQUEST_METHOD && message.kind === "notification") {
182	      const parsed = validateCancelRequest(message.params);
183	      if (parsed.ok) {
184	        const approval = this.permissionRequests.abandon(parsed.value.requestId as number);
185	        if (approval) {
186	          const session = this.sessions.get(approval.sessionId);
187	          if (session?.pendingApproval?.rpcId === parsed.value.requestId) {
188	            clearTimeout(session.pendingApproval.timer);
189	            const approvalId = session.pendingApproval.id;
190	            session.pendingApproval = undefined;
191	            await this.sidecarCommand(session, { type: "deny", id: approvalId });
192	          }
193	        }
194	        const id = this.pending.get(this.requestKey(parsed.value.requestId));
195	        for (const session of this.sessions.values()) {
196	          const verify = session.pendingVerify;
197	          if (verify && this.requestKey(verify.rpcId) === this.requestKey(parsed.value.requestId)) {
198	            verify.cancelled = true;
199	            verify.controller.abort();
200	            return;
201	          }
202	        }
203	        if (id !== undefined) {
204	          for (const session of this.sessions.values()) if (session.pendingPrompt?.rpcId === id) {
205	            session.pendingPrompt = undefined;
206	            session.stopping = true;
207	            // The permission the cancelled prompt was waiting on dies with it; left in place it would silently deny
208	            // the next prompt's first approval.
209	            await this.dropPendingApproval(session, true);
210	            await this.sidecarCommand(session, { type: "cancel" });
211	            this.send(cancelledRequestError(id));
212	            this.pending.delete(this.requestKey(id));
213	          }
214	        }
215	      }
216	      return;
217	    }
218	    if (message.method === "_nexus/receipt/get" && message.kind === "request") return this.getReceipt(message.id, message.params);
219	    if (message.kind === "request") this.replyError(message.id, { code: ACP_ERROR.METHOD_NOT_FOUND, message: `method not found: ${message.method}` });
220	  }
