222	  private canonical(cwd: string): string | undefined {
223	    const result = canonicalCwd(cwd, {
224	      realpath: this.options.realpath ?? ((value) => fs.realpathSync(value)),
225	      isDirectory: this.options.isDirectory ?? ((value) => fs.statSync(value).isDirectory()),
226	    });
227	    return result.ok ? result.value : undefined;
228	  }
