230	  private async startSession(cwd: string, mcp: { count: number; names: string[] }, resume?: string): Promise<Session | undefined> {
231	    const verifyBase = pinBase(cwd);
232	    const config = { ...this.options.config, workspace: cwd, surface: "tui" as const };
233	    const events: SidecarEvent[] = [];
234	    const early: string[] = [];
235	    let session: Session;
236	    const sink = (line: string) => session ? this.onSidecarLine(session, line) : early.push(line);
237	    const sidecar = this.options.createSidecar?.(config, resume, sink)
238	      ?? new SidecarServer({ app: new ApplicationCore(config), resume, fullHistoryReplay: resume !== undefined, write: sink });
239	    session = { id: "", cwd, mcp, sidecar, events, tools: [], verifyBase };
240	    try {
241	      sidecar.start();
242	    } catch (err) {
243	      await sidecar.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, type: "shutdown" }));
244	      throw err;
245	    }
246	    for (const line of early) this.onSidecarLine(session, line);
247	    await new Promise((resolve) => setImmediate(resolve));
248	    if (this.closed) {
249	      await sidecar.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, type: "shutdown" }));
250	      return undefined;
251	    }
252	    const state = events.find((event) => event.type === "session.state") as Extract<SidecarEvent, { type: "session.state" }> | undefined;
253	    if (!state?.session || (resume !== undefined && state.session !== resume)) {
254	      await sidecar.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, type: "shutdown" }));
255	      return undefined;
256	    }
257	    session.id = state.session;
258	    return session;
259	  }
