261	  private async newSession(id: AcpId, params: unknown): Promise<void> {
262	    const parsed = validateNewSession(params);
263	    if (!parsed.ok) { this.replyError(id, parsed.error); return; }
264	    const cwd = this.canonical(parsed.value.cwd);
265	    if (!cwd) { this.replyError(id, { code: ACP_ERROR.INVALID_PARAMS, message: "cwd does not exist or is not a readable directory" }); return; }
266	    if (this.hasVerificationOverlap(cwd)) { this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "a verification is running for this workspace; retry session creation when it finishes" }); return; }
267	    if (this.sessions.size + this.startingSessions >= ACP_MAX_SESSIONS) { this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "the connection already has the maximum number of sessions" }); return; }
268	    this.startingSessions++;
269	    try {
270	      const session = await this.startSession(cwd, parsed.value.mcpServers);
271	      if (!session) { if (!this.closed) this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "sidecar did not establish a session" }); return; }
272	      if (this.sessions.has(session.id)) { await session.sidecar.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, type: "shutdown" })); this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "the sidecar generated a duplicate session id" }); return; }
273	      this.sessions.set(session.id, session);
274	      const state = session.events.find((event) => event.type === "session.state") as any;
275	      this.send(resultResponse(id, newSessionResult(state, session.mcp) ?? { sessionId: session.id }));
276	    } finally {
277	      this.startingSessions--;
278	    }
279	  }
