281	  private async loadSession(id: AcpId, params: unknown): Promise<void> {
282	    const parsed = validateLoadSession(params);
283	    if (!parsed.ok) { this.replyError(id, parsed.error); return; }
284	    const cwd = this.canonical(parsed.value.cwd);
285	    if (!cwd) { this.replyError(id, { code: ACP_ERROR.INVALID_PARAMS, message: "cwd does not exist or is not a readable directory" }); return; }
286	    if (this.hasVerificationOverlap(cwd)) { this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "a verification is running for this workspace; retry session loading when it finishes" }); return; }
287	    if (this.sessions.has(parsed.value.sessionId) || this.loadingSessionIds.has(parsed.value.sessionId)) { this.replyError(id, { code: ACP_ERROR.INVALID_PARAMS, message: "session is already active on this connection" }); return; }
288	    if (this.sessions.size + this.startingSessions >= ACP_MAX_SESSIONS) { this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "the connection already has the maximum number of sessions" }); return; }
289	    this.startingSessions++;
290	    this.loadingSessionIds.add(parsed.value.sessionId);
291	    try {
292	      const session = await this.startSession(cwd, parsed.value.mcpServers, parsed.value.sessionId);
293	      if (!session) { if (!this.closed) this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "session could not be loaded" }); return; }
294	      const pages = session.events.filter((event): event is Extract<SidecarEvent, { type: "history" }> => event.type === "history");
295	      const first = pages[0];
296	      const valid = Boolean(first && !first.error && Number.isSafeInteger(first.total) && first.total >= 0 &&
297	        Number.isSafeInteger(first.pages) && first.pages! > 0 && first.pages! <= SIDECAR_MAX_HISTORY_PAGES &&
298	        pages.length === first.pages && pages.every((page, index) => !page.error && page.session === session.id &&
299	          page.total === first.total && page.pages === first.pages && page.page === index && Array.isArray(page.messages) &&
300	          page.messages.every((entry: unknown) => {
301	            if (!entry || typeof entry !== "object") return false;
302	            const value = entry as Record<string, unknown>;
303	            if (typeof value.text !== "string") return false;
304	            if (["user", "steering", "assistant"].includes(String(value.role))) return true;
305	            if (value.role === "tool") return (value.tool === undefined || typeof value.tool === "string") &&
306	              (value.toolCallId === undefined || typeof value.toolCallId === "string") &&
307	              (value.status === undefined || ["pending", "completed", "failed"].includes(String(value.status)));
308	            if (value.role === "tool_result") return typeof value.toolCallId === "string" &&
309	              (value.status === undefined || ["completed", "failed"].includes(String(value.status)));
310	            return value.role === "outcome" && (value.heading === undefined || typeof value.heading === "string") &&
311	              (value.text === undefined || typeof value.text === "string");
312	          })));
313	      if (!valid || !first) {
314	        await session.sidecar.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, type: "shutdown" }));
315	        this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: first?.error ?? "session history is incomplete or invalid; no history was replayed" });
316	        return;
317	      }
318	      const replay = pages.map((page) => historyToReplay(page));
319	      const extent = { sent: replay.reduce((sum, page) => sum + page.extent.sent, 0), total: first.total };
320	      if (!Number.isSafeInteger(extent.total) || extent.total < 0 || extent.sent !== extent.total) {
321	        await session.sidecar.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, type: "shutdown" }));
322	        this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "session history is incomplete; no history was replayed" });
323	        return;
324	      }
325	      for (const page of replay) for (const update of page.updates) this.send(sessionUpdate(session.id, update));
326	      this.sessions.set(session.id, session);
327	      const state = session.events.find((event) => event.type === "session.state") as any;
328	      this.send(resultResponse(id, loadSessionResult(state, session.mcp, extent)));
329	    } finally {
330	      this.startingSessions--;
331	      this.loadingSessionIds.delete(parsed.value.sessionId);
332	    }
333	  }
