335	  private async prompt(id: AcpId, params: unknown): Promise<void> {
336	    const rawSessionId = (params && typeof params === "object") ? (params as any).sessionId : undefined;
337	    const session = typeof rawSessionId === "string" ? this.sessions.get(rawSessionId) : undefined;
338	    if (!session) { this.replyError(id, { code: ACP_ERROR.INVALID_PARAMS, message: "sessionId is not active on this connection" }); return; }
339	    if (this.hasVerificationOverlap(session.cwd)) { this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "a verification is running for this workspace; retry the prompt when it finishes" }); return; }
340	    const parsed = validatePrompt(params, { workspace: session.cwd, fs: { realpath: (value) => fs.realpathSync(value), isDirectory: (value) => fs.statSync(value).isDirectory() } });
341	    if (!parsed.ok) { this.replyError(id, parsed.error); return; }
342	    if (session.pendingPrompt) { this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "this session already has a prompt in progress" }); return; }
343	    if (session.stopping) { this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "the previous prompt of this session is still stopping; send the prompt again" }); return; }
344	    const commandId = `acp-${String(id).slice(0, 180)}`;
345	    session.pendingPrompt = { rpcId: id, commandId };
346	    await this.sidecarCommand(session, { type: "prompt.submit", id: commandId, text: parsed.value.text });
347	  }
