349	  private async getReceipt(id: AcpId, params: unknown): Promise<void> {
350	    const parsed = validateReceiptGet(params);
351	    if (!parsed.ok) { this.replyError(id, parsed.error); return; }
352	    const explicitReceiptId = parsed.value.receiptId !== undefined;
353	    const receiptId = parsed.value.receiptId ?? this.latestReceipts.get(parsed.value.sessionId);
354	    if (receiptId) {
355	      const verificationReceipt = this.verifyService.receipt(receiptId, parsed.value.sessionId);
356	      if (verificationReceipt) {
357	        this.send(resultResponse(id, { ...verificationReceipt, surface: "acp", session_id: parsed.value.sessionId }));
358	        return;
359	      }
360	    }
361	    const receipt = receiptId ? this.receipts.get(receiptId) : [...this.receipts.values()].reverse().find((value) => value.session_id === parsed.value.sessionId);
362	    if (!explicitReceiptId && !receipt) {
363	      const latestTurn = [...this.receipts.values()].reverse().find((value) => value.session_id === parsed.value.sessionId);
364	      if (latestTurn) { this.send(resultResponse(id, latestTurn)); return; }
365	    }
366	    if (!receipt || receipt.session_id !== parsed.value.sessionId) { this.replyError(id, { code: ACP_ERROR.INVALID_PARAMS, message: "receipt is not available on this connection" }); return; }
367	    this.send(resultResponse(id, receipt));
368	  }
