370	  private hasVerificationOverlap(cwd: string): boolean {
371	    return [...this.sessions.values()].some((session) => session.pendingVerify && this.workspacesOverlap(cwd, session.cwd));
372	  }
373	
374	  private hasPromptOverlap(cwd: string): boolean {
375	    return [...this.sessions.values()].some((session) => (session.pendingPrompt || session.stopping) && this.workspacesOverlap(cwd, session.cwd));
376	  }
377	
378	  private workspacesOverlap(left: string, right: string): boolean {
379	    const within = (parent: string, child: string) => {
380	      const relative = path.relative(parent, child);
381	      return relative === "" || (!path.isAbsolute(relative) && relative !== ".." && !relative.startsWith(`..${path.sep}`));
382	    };
383	    return within(left, right) || within(right, left);
384	  }
