386	  private async verify(id: AcpId, params: unknown): Promise<void> {
387	    const parsed = validateVerify(params);
388	    if (!parsed.ok) { this.replyError(id, parsed.error); return; }
389	    const session = this.sessions.get(parsed.value.sessionId);
390	    if (!session) { this.replyError(id, { code: ACP_ERROR.INVALID_PARAMS, message: "sessionId is not active on this connection" }); return; }
391	    if (this.startingSessions > 0) {
392	      this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "verification cannot run while an ACP session is starting or loading" });
393	      return;
394	    }
395	    if (this.hasPromptOverlap(session.cwd)) {
396	      this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "verification cannot run while a session turn is active or stopping" });
397	      return;
398	    }
399	    if (this.hasVerificationOverlap(session.cwd)) {
400	      this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "a verification is already running for this workspace" });
401	      return;
402	    }
403	    if ("error" in session.verifyBase) {
404	      this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: session.verifyBase.error });
405	      return;
406	    }
407	    const pending: NonNullable<Session["pendingVerify"]> = { rpcId: id, controller: new AbortController(), cancelled: false };
408	    session.pendingVerify = pending;
409	    try {
410	      const completion = this.verifyService.verify({ sessionId: session.id, worktree: session.cwd, base: session.verifyBase }, pending.controller.signal);
411	      pending.completion = completion;
412	      const outcome = await completion;
413	      if (pending.cancelled) { this.send(cancelledRequestError(id)); return; }
414	      if ("error" in outcome) {
415	        this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: `verification did not produce a verdict: ${outcome.error.message}`, data: { reason: outcome.error.kind } });
416	        return;
417	      }
418	      this.latestReceipts.set(session.id, outcome.summary.receipt_id);
419	      this.send(resultResponse(id, outcome.summary));
420	    } finally {
421	      if (session.pendingVerify === pending) session.pendingVerify = undefined;
422	    }
423	  }
