460	  /** Forget the session's open permission request: stop its timer, stop accepting a reply, and (optionally) deny it. */
461	  private async dropPendingApproval(session: Session, deny: boolean): Promise<void> {
462	    const approval = session.pendingApproval;
463	    if (!approval) return;
464	    clearTimeout(approval.timer);
465	    this.permissionRequests.abandon(approval.rpcId);
466	    session.pendingApproval = undefined;
467	    if (deny) await this.sidecarCommand(session, { type: "deny", id: approval.id });
468	  }
