470	  /**
471	   * A checkpoint that cannot be made asks the operator how to go on. No ACP client may answer that, and the adapter
472	   * never picks read-only, no-checkpoint or allow-sensitive for the operator: it cancels, and the prompt fails with
473	   * the sidecar's message.
474	   */
475	  private checkpointChoice(session: Session, event: Extract<SidecarEvent, { type: "checkpoint.choice.request" }>): void {
476	    const prompt = session.pendingPrompt;
477	    if (prompt) {
478	      session.pendingPrompt = undefined;
479	      session.stopping = true;
480	      this.replyError(prompt.rpcId, { code: ACP_ERROR.INTERNAL_ERROR, message: formatSafeSidecarDiagnostic([event.message]) });
481	      this.pending.delete(this.requestKey(prompt.rpcId));
482	    }
483	    void this.sidecarCommand(session, { type: "checkpoint.choice", id: event.id, choice: "cancel" });
484	  }
485	
486	  private permission(session: Session, event: Extract<SidecarEvent, { type: "approval.request" }>): void {
487	    if (session.pendingApproval || ACP_MAX_PENDING_PERMISSIONS_PER_SESSION !== 1) {
488	      void this.sidecarCommand(session, { type: "deny", id: event.id }); return;
489	    }
490	    const toolCallId = bindApprovalToToolCall(event as any, session.tools as any);
491	    const rpcId = this.permissionRequests.open({ sessionId: session.id, approvalId: event.id });
492	    const timer = setTimeout(() => {
493	      this.permissionRequests.abandon(rpcId);
494	      if (session.pendingApproval?.rpcId === rpcId) session.pendingApproval = undefined;
495	      void this.sidecarCommand(session, { type: "deny", id: event.id });
496	    }, ACP_PERMISSION_TIMEOUT_SECS * 1000);
497	    timer.unref?.();
498	    session.pendingApproval = { id: event.id, rpcId, toolCallId, timer };
499	    this.send(approvalToPermissionRequest(event as any, { rpcId, sessionId: session.id, toolCallId, workspace: session.cwd }));
500	  }
501	
502	  private async finishPrompt(session: Session, event: Extract<SidecarEvent, { type: "turn.result" }>): Promise<void> {
503	    const pending = session.pendingPrompt;
504	    // The turn is over, so nothing can still be waiting on a permission, whether or not a prompt is waiting on the turn.
505	    session.stopping = false;
506	    await this.dropPendingApproval(session, false);
507	    if (!pending) { session.tools = []; return; }
508	    // From here the prompt is being answered. It stops being cancellable now, before the receipt is awaited: a
509	    // $/cancel_request in that window would otherwise answer it a second time and wait for a turn that has ended.
510	    session.pendingPrompt = undefined;
511	    session.tools = [];
512	    const resultId = `acp-receipt-${pending.commandId}`;
513	    let sections: any[] = [];
514	    try {
515	      const detail = await new Promise<SidecarEvent | undefined>((resolve) => {
516	        const timer = setTimeout(() => { if (session.pendingReceipt?.commandId === resultId) session.pendingReceipt = undefined; resolve(undefined); }, 2_000);
517	        session.pendingReceipt = { commandId: resultId, resolve: (value) => { clearTimeout(timer); resolve(value); } };
518	        void this.sidecarCommand(session, { type: "receipt", id: resultId });
519	      });
520	      if (detail?.type === "receipt") sections = detail.sections;
521	    } catch { /* A missing receipt is represented as missing evidence, never as a passed verifier. */ }
522	    const turnId = event.turn_id ?? null;
523	    const verification: AcpVerification = verificationFromTurn({ sessionId: session.id, turnId, turn: event.turn, sections });
524	    const receipt = nexusReceipt(session.id, verification, sections);
525	    this.receipts.set(receipt.receipt_id, receipt);
526	    this.latestReceipts.set(session.id, receipt.receipt_id);
527	    while (this.receipts.size > ACP_RECEIPT_STORE_SIZE) this.receipts.delete(this.receipts.keys().next().value as string);
528	    const mapped = turnToStop(event.turn);
529	    this.send(sessionUpdate(session.id, verificationUpdate(verification) as any));
530	    this.send(sessionUpdate(session.id, verdictChunk(event.heading, event.line)));
531	    if ("error" in mapped) this.replyError(pending.rpcId, mapped.error);
532	    else this.send(resultResponse(pending.rpcId, promptResult(mapped.stopReason, verification)));
533	    this.pending.delete(this.requestKey(pending.rpcId));
534	  }
535	}
