537	/**
538	 * Why `nexus acp` must not start with this configuration, or undefined. Only review and read-only are served: the
539	 * client on the other end is untrusted, and auto approval would let every tool call through without asking it.
540	 */
541	export function acpStartupRefusal(config: Pick<HarnessConfig, "approvalMode" | "fullAccess">): string | undefined {
542	  if (config.approvalMode !== "auto" && !config.fullAccess) return undefined;
543	  return "nexus acp does not run with automatic approval (--yes, --mode auto or NEXUS_APPROVAL_MODE=auto). Start it in review mode (the default) or with --read-only.";
544	}
