546	/** Attach the adapter to process stdio. Stdout is reserved for JSON-RPC messages. */
547	export function runAcpStdio(options: AcpStdioOptions): AcpStdioServer {
548	  const protocolWrite = process.stdout.write.bind(process.stdout);
549	  // ACP owns stdout for the lifetime of this command; incidental logs must never corrupt the wire stream.
550	  (process.stdout as any).write = (_chunk: unknown, encoding?: unknown, callback?: unknown): boolean => {
551	    const done = typeof encoding === "function" ? encoding : callback;
552	    if (typeof done === "function") queueMicrotask(done as () => void);
553	    return true;
554	  };
555	  const server = new AcpStdioServer({ ...options, write: options.write ?? ((line) => protocolWrite(line)) });
556	  process.stdin.on("data", (chunk: Buffer) => server.push(chunk));
557	  process.stdin.once("end", () => { void server.close(); });
558	  // The stdin listener keeps the process alive, so setting an exit code would leave it running after a signal.
559	  // close() waits for every session to stop. A session that never does must not keep a signalled process alive.
560	  const stop = (code: number) => {
561	    const deadline = setTimeout(() => process.exit(code), options.shutdownGraceMs ?? ACP_SHUTDOWN_GRACE_MS);
562	    void server.close().finally(() => {
563	      clearTimeout(deadline);
564	      process.exit(code);
565	    });
566	  };
567	  process.once("SIGINT", () => stop(130));
568	  process.once("SIGTERM", () => stop(143));
569	  return server;
570	}
