268	export class VerifyService {
269	  private readonly config: VerifyServiceConfig;
270	  private readonly timeoutSecs: number;
271	  private readonly run: VerifyRunner;
272	  private readonly policy: () => EffectivePolicy;
273	  private readonly now: () => Date;
274	  private readonly random: () => string;
275	  private readonly watchdogMs: number;
276	  /** Insertion-ordered, so the first key is the oldest receipt. Each entry keeps the exact text it is served as. */
277	  private readonly receipts = new Map<string, { receipt: VerifyServiceReceipt; text: string }>();
278	  private running: AbortController | undefined;
279	  /** Resolves when the running verification has settled: its worker and what the worker started are gone. */
280	  private settled: Promise<void> | undefined;
281	
282	  constructor(config: VerifyServiceConfig, deps: VerifyServiceDeps = {}) {
283	    this.config = { ...config, deliverables: [...config.deliverables] };
284	    this.timeoutSecs = verifierTimeoutSecs(config.timeoutSecs);
285	    this.policy = deps.policy ?? managedPolicy;
286	    this.now = deps.now ?? (() => new Date());
287	    this.random = deps.random ?? (() => randomBytes(16).toString("hex"));
288	    this.watchdogMs = deps.watchdogMs ?? (6 * this.timeoutSecs + 300) * 1000;
289	    const here = import.meta.url;
290	    this.run = deps.run ?? forkRunner(deps.workerModule ?? new URL(`./verify_worker${here.endsWith(".ts") ? ".ts" : ".js"}`, here), deps.killGraceMs ?? VERIFY_KILL_GRACE_MS);
291	  }
292	
293	  /**
294	   * Verifies the working tree against the pinned base. Every verdict, BLOCKED included, comes back with a receipt; an
295	   * error means no verdict was reached and nothing was stored. One verification runs at a time: a second call is
296	   * refused, not queued.
297	   */
298	  async verify(binding: VerifyBinding, signal?: AbortSignal): Promise<VerifyServiceOutcome> {
299	    const refuse = (kind: VerifyServiceErrorKind, message: string): VerifyServiceOutcome => ({ error: { kind, message } });
300	    if (this.config.readOnly) return refuse("read_only", "verification runs repository code, which read-only mode does not allow");
301	    try {
302	      const human = humanRequirementForEffect(this.policy(), "exec");
303	      if (human) return refuse("policy_requires_human", `managed policy requires a person to approve command execution, and no person decides a remote verification: ${human.message}`);
304	    } catch (error) {
305	      return refuse("policy_error", `the managed policy could not be read, so verification is refused: ${error instanceof Error ? error.message : String(error)}`);
306	    }
307	    const worktree = binding.worktree ?? this.config.worktree;
308	    if (!worktree) return refuse("no_workspace", "no workspace is bound to this verification");
309	    if (this.running) return refuse("busy", "a verification is already running; this one was not started and is not queued");
310	    if (signal?.aborted) return refuse("interrupted", "interrupted: no verdict was reached");
311	
312	    const controller = new AbortController();
313	    this.running = controller;
314	    let settle!: () => void;
315	    this.settled = new Promise((resolve) => (settle = resolve));
316	    let timedOut = false;
317	    const watchdog = setTimeout(() => {
318	      timedOut = true;
319	      controller.abort();
320	    }, this.watchdogMs);
321	    const onAbort = () => controller.abort();
322	    signal?.addEventListener("abort", onAbort, { once: true });
323	    try {
324	      const reply = await this.run(
325	        { tag: VERIFY_WORKER_TAG, request: { worktree, base: binding.base.commit }, operator: { verifierCommand: this.config.verifierCommand, deliverables: this.config.deliverables, timeoutSecs: this.timeoutSecs } },
326	        controller.signal,
327	      );
328	      // After an abort nothing the worker sent is a verdict, whatever arrived first.
329	      if (timedOut) return refuse("timeout", `verification did not finish within ${Math.round(this.watchdogMs / 1000)} s and was stopped: no verdict was reached`);
330	      if (controller.signal.aborted || "interrupted" in reply) return refuse("interrupted", "interrupted: no verdict was reached");
331	      if ("usage" in reply) return refuse("usage", String(reply.usage));
332	      if (!("result" in reply)) return refuse("worker_failed", `verification could not be run: ${"failed" in reply ? String(reply.failed) : "the worker sent no result"}`);
333	      return this.issue(reply.result, binding, worktree);
334	    } catch (error) {
335	      return refuse("worker_failed", `verification could not be run: ${error instanceof Error ? error.message : String(error)}`);
336	    } finally {
337	      clearTimeout(watchdog);
338	      signal?.removeEventListener("abort", onAbort);
339	      this.running = undefined;
340	      this.settled = undefined;
341	      settle();
342	    }
343	  }
344	
345	  private issue(raw: VerifyJsonResult, binding: VerifyBinding, worktree: string): VerifyServiceOutcome {
346	    let served: string;
347	    try {
348	      served = JSON.stringify(raw);
349	    } catch {
350	      return { error: { kind: "worker_failed", message: "verification could not be run: the result is not a JSON document" } };
351	    }
352	    if (typeof served !== "string" || Buffer.byteLength(served, "utf8") > VERIFY_MAX_RESULT_BYTES) {
353	      return { error: { kind: "too_large", message: `the verification result exceeds ${VERIFY_MAX_RESULT_BYTES} bytes and was discarded: no receipt was created` } };
354	    }
355	    // Through JSON, so the stored document is plain data and owes nothing to the object the runner returned.
356	    const result = JSON.parse(served) as VerifyJsonResult;
357	    if (result?.schema_version !== VERIFY_RESULT_SCHEMA_VERSION || !VERDICTS.includes(result.verdict)) {
358	      return { error: { kind: "worker_failed", message: "verification could not be run: the worker's result is not a verify result document" } };
359	    }
360	    const receiptId = `vr-${this.random()}`;
361	    const issuedAt = this.now().toISOString();
362	    let workspace = worktree;
363	    try { workspace = fs.realpathSync(worktree); } catch { /* the path as given */ }
364	    const receipt: VerifyServiceReceipt = deepFreeze({
365	      receipt_id: receiptId,
366	      receipt_sha256: createHash("sha256").update(JSON.stringify(result), "utf8").digest("hex"),
367	      issued_at: issuedAt,
368	      surface: this.config.surface,
369	      session_id: binding.sessionId ?? null,
370	      workspace,
371	      base_pinned_at: binding.base.at,
372	      result,
373	    });
374	    if (!RECEIPT_ID.test(receiptId) || this.receipts.has(receiptId)) {
375	      return { error: { kind: "worker_failed", message: "verification could not be recorded: no receipt id could be drawn" } };
376	    }
377	    this.receipts.set(receiptId, { receipt, text: JSON.stringify(receipt) });
378	    while (this.receipts.size > VERIFY_RECEIPT_STORE_SIZE) this.receipts.delete(this.receipts.keys().next().value!);
379	
380	    const command = this.config.surface === "mcp" ? "serve-mcp" : "acp";
381	    const hint = result.reason === "VERIFIER_NOT_APPROVED" || result.reason === "NO_APPLICABLE_VERIFIER"
382	      ? `Only the operator's own verifier runs here: the operator must start the server with \`nexus --authoritative-verifier <command> ${command}\`.`
383	      : result.reason === "REGRESSION_FREE" && this.config.deliverables.length === 0
384	        ? `VERIFIED needs the operator to declare the product files: \`nexus --deliverable-file <path> ${command}\`.`
385	        : undefined;
386	    const summary: VerifyServiceSummary = {
387	      service_version: VERIFY_SERVICE_VERSION,
388	      receipt_id: receiptId,
389	      receipt_uri: `${VERIFY_RECEIPT_URI_PREFIX}${receiptId}`,
390	      receipt_sha256: receipt.receipt_sha256,
391	      verify_schema_version: result.schema_version,
392	      verdict: result.verdict,
393	      outcome: result.outcome,
394	      ...(result.reason !== undefined ? { reason: result.reason } : {}),
395	      ...(result.detail !== undefined ? { detail: result.detail } : {}),
396	      ...(result.base ? { base: { commit: result.base.commit, tree: result.base.tree } } : {}),
397	      ...(result.head ? { head: { tree: result.head.tree, workingTree: result.head.workingTree } } : {}),
398	      ...(result.verifier ? { verifier: { command: result.verifier.command, source: result.verifier.source, approval: result.verifier.approval, digest: result.verifier.digest } } : {}),
399	      ...(hint ? { operator_hint: hint } : {}),
400	      issued_at: issuedAt,
401	    };
402	    return { summary, receipt };
403	  }
404	
405	  /** A stored receipt and its text. Anything that is not a well-formed id issued to this session is simply not there. */
406	  private lookup(id: unknown, sessionId: string | null): { receipt: VerifyServiceReceipt; text: string } | undefined {
407	    if (typeof id !== "string" || !RECEIPT_ID.test(id)) return undefined;
408	    const entry = this.receipts.get(id);
409	    return entry && entry.receipt.session_id === sessionId ? entry : undefined;
410	  }
411	
412	  receipt(id: unknown, sessionId: string | null = null): VerifyServiceReceipt | undefined {
413	    return this.lookup(id, sessionId)?.receipt;
414	  }
415	
416	  /** The receipt as it is served: the same bytes on every read. */
417	  receiptText(id: unknown, sessionId: string | null = null): string | undefined {
418	    return this.lookup(id, sessionId)?.text;
419	  }
420	
421	  /** The retained receipts of a session, oldest first. */
422	  list(sessionId: string | null = null): Array<{ receipt_id: string; issued_at: string; verdict: string }> {
423	    return [...this.receipts.values()]
424	      .filter(({ receipt }) => receipt.session_id === sessionId)
425	      .map(({ receipt }) => ({ receipt_id: receipt.receipt_id, issued_at: receipt.issued_at, verdict: receipt.result.verdict }));
426	  }
427	
428	  /** Stops the running verification, if any; its caller gets an error and no receipt. */
429	  abort(): void {
430	    this.running?.abort();
431	  }
432	
433	  /** Stops the running verification and resolves once nothing of it is left running. */
434	  async stop(): Promise<void> {
435	    this.abort();
436	    await this.settled;
437	  }
438	}
