36	  pendingReceipt?: { commandId: string; resolve: (event: SidecarEvent | undefined) => void };
37	  /** The prompt was answered early (cancelled request, refused checkpoint) and its turn is still winding down: no new prompt until the turn's result arrives, or that result would answer the new prompt. */
38	  stopping?: boolean;
39	};
