41	export interface AcpStdioOptions {
42	  config: HarnessConfig;
43	  version: string;
44	  write?: (line: string) => void;
45	  createSidecar?: (config: HarnessConfig, resume: string | undefined, write: (line: string) => void) => SidecarLike;
46	  realpath?: (value: string) => string;
47	  isDirectory?: (value: string) => boolean;
48	  /** How long a signalled process waits for its sessions to stop before it exits anyway. */
49	  shutdownGraceMs?: number;
50	  verifyDeps?: VerifyServiceDeps;
