199	            verify.controller.abort();
200	            return;
201	          }
202	        }
203	        if (id !== undefined) {
204	          for (const session of this.sessions.values()) if (session.pendingPrompt?.rpcId === id) {
205	            session.pendingPrompt = undefined;
206	            session.stopping = true;
