212	            this.pending.delete(this.requestKey(id));
213	          }
214	        }
215	      }
216	      return;
217	    }
218	    if (message.method === "_nexus/receipt/get" && message.kind === "request") return this.getReceipt(message.id, message.params);
219	    if (message.kind === "request") this.replyError(message.id, { code: ACP_ERROR.METHOD_NOT_FOUND, message: `method not found: ${message.method}` });
220	  }
