429	  private onSidecarLine(session: Session | undefined, line: string): void {
430	    if (!session) return;
431	    let event: SidecarEvent;
432	    try { event = JSON.parse(line); } catch { return; }
433	    session.events.push(event);
434	    if (session.events.length > 2_000) session.events.shift();
435	    if (event.type === "tool.start") {
436	      session.tools.push(event);
437	      this.send(sessionUpdate(session.id, toolStartToUpdate(event as any)));
438	    } else if (event.type === "assistant.delta") this.send(sessionUpdate(session.id, assistantDeltaToUpdate(event as any)));
439	    else if (event.type === "file.diff") this.send(sessionUpdate(session.id, fileDiffToUpdate(event as any, session.cwd)));
440	    else if (event.type === "tool.end") this.send(sessionUpdate(session.id, toolEndToUpdate(event as any)));
441	    else if (event.type === "approval.request") this.permission(session, event as any);
442	    else if (event.type === "checkpoint.choice.request") this.checkpointChoice(session, event);
443	    else if (event.type === "turn.result") void this.finishPrompt(session, event as any);
444	    else if (event.type === "error" && session.pendingPrompt && event.id === session.pendingPrompt.commandId) {
445	      this.replyError(session.pendingPrompt.rpcId, sidecarErrorToRpc(event as any));
446	      this.pending.delete(this.requestKey(session.pendingPrompt.rpcId));
447	      session.pendingPrompt = undefined;
448	    }
449	    if (session.pendingReceipt && event.type === "receipt" && event.id === session.pendingReceipt.commandId) {
450	      const pending = session.pendingReceipt; session.pendingReceipt = undefined; pending.resolve(event);
451	    }
452	    if (event.type === "session.state") {
453	      if (!session.id && event.session) session.id = event.session;
454	      // A pre-turn refusal (for example a cancelled checkpoint choice or provider-gate cancellation) ends with a
455	      // terminal `error`, not `turn.result`. Keep the session blocked until Sidecar confirms its job is idle.
456	      if (session.stopping && event.busy === false) session.stopping = false;
457	    }
458	  }
