470	  /**
471	   * A checkpoint that cannot be made asks the operator how to go on. No ACP client may answer that, and the adapter
472	   * never picks read-only, no-checkpoint or allow-sensitive for the operator: it cancels, and the prompt fails with
473	   * the sidecar's message.
474	   */
475	  private checkpointChoice(session: Session, event: Extract<SidecarEvent, { type: "checkpoint.choice.request" }>): void {
476	    const prompt = session.pendingPrompt;
477	    if (prompt) {
478	      session.pendingPrompt = undefined;
479	      session.stopping = true;
480	      this.replyError(prompt.rpcId, { code: ACP_ERROR.INTERNAL_ERROR, message: formatSafeSidecarDiagnostic([event.message]) });
481	      this.pending.delete(this.requestKey(prompt.rpcId));
482	    }
483	    void this.sidecarCommand(session, { type: "checkpoint.choice", id: event.id, choice: "cancel" });
484	  }
