138	/** Every process below any of `roots`, from one process listing. */
139	function descendants(roots: readonly number[]): number[] {
140	  const listing = spawnSync("ps", ["-A", "-o", "pid=,ppid="], { encoding: "utf8", timeout: 5_000 });
141	  const children = new Map<number, number[]>();
142	  for (const line of (listing.stdout ?? "").split("\n")) {
143	    const [pid, parent] = line.trim().split(/\s+/).map(Number);
144	    if (pid > 0 && parent > 0) children.set(parent, [...(children.get(parent) ?? []), pid]);
145	  }
146	  const found = new Set<number>();
147	  for (const queue = [...roots]; queue.length;) {
148	    for (const pid of children.get(queue.shift()!) ?? []) {
149	      if (found.has(pid)) continue;
150	      found.add(pid);
151	      queue.push(pid);
152	    }
153	  }
154	  return [...found];
155	}
