172	function forkRunner(workerModule: URL, killGraceMs: number): VerifyRunner {
173	  return (job, signal) => new Promise((resolve) => {
174	    const file = fileURLToPath(workerModule);
175	    const child = fork(file, [], {
176	      detached: true,
177	      // Stdout is not connected: nothing the worker or a verifier prints can reach the server's protocol stream.
178	      stdio: ["ignore", "ignore", "inherit", "ipc"],
179	      execArgv: file.endsWith(".ts") ? ["--import", import.meta.resolve("tsx")] : [],
180	    });
181	    let reply: VerifyWorkerReply | undefined;
182	    let killTimer: NodeJS.Timeout | undefined;
183	    let settled = false;
184	    // A verifier runs under `timeout`, which leaves the worker's process group, so the group alone does not reach it:
185	    // every descendant is signalled by its own pid.
186	    // Every process seen below the worker, with the time it started. A sandbox whose parent dies on SIGTERM while it
187	    // ignores the signal itself is handed to init: no later listing finds it under the worker, so it is remembered
188	    // here, and the start time tells it from an unrelated process that was given the same pid since.
189	    const seen = new Map<number, string>();
190	    const signalTree = (name: NodeJS.Signals, worker = true, passes = KILL_LISTING_PASSES) => {
191	      if (child.pid === undefined) return;
192	      const send = (pid: number, signal: NodeJS.Signals) => { try { process.kill(pid, signal); } catch { /* already gone */ } };
193	      // Once the worker has exited, its pid may belong to another process: it is then neither signalled nor searched.
194	      const workerPid = child.exitCode === null && child.signalCode === null ? child.pid : undefined;
195	      const survivors = () => [...seen].filter(([pid, started]) => startedAt(pid) === started).map(([pid]) => pid);
196	      const list = () => {
197	        const remembered = survivors();
198	        const found = [...new Set([...remembered, ...descendants([...(workerPid === undefined ? [] : [workerPid]), ...remembered])])];
199	        for (const pid of found) if (!seen.has(pid)) { const started = startedAt(pid); if (started !== undefined) seen.set(pid, started); }
200	        return found;
201	      };
202	      // One listing cannot promise that nothing is missed: a process on the list may fork after it was listed (timeout
203	      // starting the sandbox, the sandbox starting its inner process), and a newcomer whose parent then dies of the
204	      // signal is handed to init unseen. So the tree is stopped first, from the top down, one listing at a time: a
205	      // stopped process starts nothing, and each further listing can only add what was started before its parent
206	      // stopped. The worker is stopped too, since the moment a verifier dies it may start the next.
207	      if (workerPid !== undefined) send(workerPid, "SIGSTOP");
208	      const stopped = new Set<number>();
209	      let targets = list();
210	      for (let pass = 0; pass < passes; pass++) {
211	        const fresh = targets.filter((pid) => !stopped.has(pid));
212	        if (!fresh.length) break;
213	        for (const pid of fresh) { send(pid, "SIGSTOP"); stopped.add(pid); }
214	        targets = list();
215	      }
216	      // What the last listing added was never stopped, and is signalled all the same.
217	      for (const pid of new Set([...stopped, ...targets])) send(pid, name);
218	      if (worker && workerPid !== undefined) {
219	        send(workerPid, name);
220	        send(-workerPid, name);
221	      }
222	      // What was not killed goes on: a process handles SIGTERM only once it runs again, and a spared worker has its
223	      // scratch trees to remove.
224	      if (name !== "SIGKILL") for (const pid of stopped) send(pid, "SIGCONT");
225	      if (workerPid !== undefined && (name !== "SIGKILL" || !worker)) send(workerPid, "SIGCONT");
226	    };
227	    const onAbort = () => {
228	      // SIGTERM ends the running verifier, which lets the worker remove its scratch trees and exit.
229	      signalTree("SIGTERM");
230	      // A verifier that ignores SIGTERM is killed first and the worker spared, so the scratch trees are still removed;
231	      // a worker that does not finish even then is killed with whatever it has started since.
232	      killTimer = setTimeout(() => {
233	        signalTree("SIGKILL", false);
234	        killTimer = setTimeout(() => signalTree("SIGKILL"), killGraceMs);
235	      }, killGraceMs);
236	    };
237	    // The server is exiting: one listing after the first, so a process listing that hangs cannot hold the exit for long.
238	    const onProcessExit = () => signalTree("SIGKILL", true, 1);
239	    const finish = (final: VerifyWorkerReply) => {
240	      if (settled) return;
241	      settled = true;
242	      clearTimeout(killTimer);
243	      // A cancelled worker can exit while something it started lives on: the later stages will not run now.
244	      if (signal.aborted) signalTree("SIGKILL", false);
245	      signal.removeEventListener("abort", onAbort);
246	      process.removeListener("exit", onProcessExit);
247	      resolve(final);
248	    };
249	    // The channel closes after its last message is read, so the reply is complete only once both have happened.
250	    let open = 2;
251	    const closed = () => {
252	      if (--open === 0) finish(reply ?? { failed: "the verification worker ended without a result" });
253	    };
254	    child.once("exit", closed);
255	    child.once("disconnect", closed);
256	    child.once("error", (error) => finish({ failed: `the verification worker could not be started: ${error.message}` }));
257	    child.on("message", (message: any) => {
258	      if (message?.tag !== VERIFY_WORKER_TAG) return;
259	      if (message.ready === true) child.send(job, () => { /* a worker that is already gone is reported by its exit */ });
260	      else reply ??= message as VerifyWorkerReply;
261	    });
262	    process.once("exit", onProcessExit);
263	    if (signal.aborted) onAbort();
264	    else signal.addEventListener("abort", onAbort, { once: true });
265	  });
266	}
